templates.template:
.tylVideoPlayer .tylVideoPlayerAd {
    position: absolute;
    inset: 0;
    z-index: 50;
    background: #000;
    color: #fff;
    pointer-events: auto;
}
.tylVideoPlayerAd[hidden] {
    display: none;
}
.tylVideoPlayerAd > video {
    display: block;
    width: 100%;
    height: 100%;
    object-fit: contain;
}
.tylVideoPlayerAd .taVideoAd-overlay {
    z-index: 1;
    flex-wrap: wrap;
}
.tylVideoPlayerAd .taVideoAd-actions {
    flex-wrap: wrap;
}
.fancybox__content.tylVideoPlayerLightboxContent {
    width: ~"min(960px, calc(100vw - 48px))";
    max-width: 100%;
    padding: 0;
}
.tylVideoPlayerLightbox {
    width: 100%;
}
.bbMediaWrapper-inner.tylVideoPlayerInner {
    padding-bottom: 0;
    height: auto;
}
.tylVideoPlayer .tylVideoPlayerAnnounce,
media-player.tylVideoPlayer [data-media-announcer] {
    position: absolute;
    display: block;
    width: 1px;
    height: 1px;
    margin: -1px;
    padding: 0;
    border: 0;
    overflow: hidden;
    clip-path: inset(50%);
    white-space: nowrap;
    pointer-events: none;
}
.tylVideoPlayerPlaylist > .button:focus-visible {
    outline: 2px solid currentColor;
    outline-offset: -3px;
}
.tylVideoPlayerPlaylist {
    position: absolute;
    z-index: 20;
    top: ~"calc(8px + env(safe-area-inset-top, 0px))";
    right: ~"calc(8px + env(safe-area-inset-right, 0px))";
    left: ~"calc(8px + env(safe-area-inset-left, 0px))";
    display: flex;
    flex-wrap: nowrap;
    justify-content: flex-start;
    overflow-x: auto;
    overscroll-behavior-x: contain;
    touch-action: pan-x pinch-zoom;
    gap: 6px;
    pointer-events: none;
}
.tylVideoPlayerPlaylist[hidden] {
    display: none;
}
.tylVideoPlayerPlaylist > * {
    flex: 0 0 auto;
    max-inline-size: 100%;
    pointer-events: auto;
}
media-player.tylVideoPlayer[data-tyl-playlist],
.tylVideoPlayer--videojs10 tyl-video-skin[data-tyl-playlist] {
    --tyl-playlist-space: 48px;
}
media-player.tylVideoPlayer[data-tyl-playlist] .vds-controls {
    padding-block-start: ~"calc(var(--tyl-playlist-space) + env(safe-area-inset-top, 0px))";
}
.tylVideoPlayer--videojs10 tyl-video-skin[data-tyl-playlist]::part(tyl-secondary-controls) {
    top: ~"calc(var(--tyl-playlist-space) + env(safe-area-inset-top, 0px))";
}
@media (any-pointer: coarse) {
    .tylVideoPlayerPlaylist > .button {
        display: inline-flex;
        align-items: center;
        justify-content: center;
        min-block-size: 44px;
        min-inline-size: 44px;
        touch-action: manipulation;
    }
    media-player.tylVideoPlayer[data-tyl-playlist],
    .tylVideoPlayer--videojs10 tyl-video-skin[data-tyl-playlist] {
        --tyl-playlist-space: 60px;
        min-block-size: ~"min(240px, 100dvh)";
    }
    .tylVideoPlayer--videojs10 tyl-video-skin[data-tyl-playlist]::part(tyl-container) {
        min-block-size: ~"min(240px, 100dvh)";
    }
}
media-player.tylVideoPlayer[data-tyl-pip-disabled] .vds-pip-button {
    display: none;
}
.tylVideoPlayer--videojs10 video-player {
    position: relative;
    display: block;
}
.tylVideoPlayer--videojs10 tyl-audio-player {
    position: relative;
    display: flex;
    flex-direction: column;
    align-items: stretch;
}
.tylVideoPlayerAudioAirPlay {
    align-self: flex-end;
    margin-block-start: 4px;
}
.tylVideoPlayerAudioAirPlay[hidden] {
    display: none;
}
.bbMediaWrapper-inner > media-player.tylVideoPlayer {
    position: relative;
    width: 100%;
    height: auto;
    max-width: 100%;
    aspect-ratio: 16 / 9;
    --media-brand: @xf-linkColor;
    font-family: @xf-fontFamilyUi;
}
.bbMediaWrapper-inner > media-player.tylVideoPlayer[data-view-type="audio"] {
    aspect-ratio: auto;
    min-height: 80px;
}
.bbMediaWrapper-inner--audio.tylVideoPlayerInner {
    height: auto;
    min-height: 80px;
}
.bbMediaWrapper-inner > .tylVideoPlayer--videojs10 {
    position: relative;
    width: 100%;
    height: auto;
    max-width: 100%;
    --media-accent-color: @xf-linkColor;
    --media-font-family: @xf-fontFamilyUi;
}
.tylVideoPlayer--videojs10 media-i18n {
    display: contents;
}
.tylVideoPlayer--videojs10 youtube-video {
    min-inline-size: 0;
    min-block-size: 0;
}
.tylVideoPlayer--videojs10 tyl-video-skin:has(> youtube-video),
.tylVideoPlayer--videojs10 tyl-video-skin:has(> youtube-video)::part(tyl-container) {
    min-block-size: ~"min(200px, 100dvh)";
}
.tylVideoPlayer--videojs10 video-skin,
.tylVideoPlayer--videojs10 tyl-video-skin {
    display: block;
    width: 100%;
    aspect-ratio: 16 / 9;
}
.tylVideoPlayer--videojs10 audio-skin {
    display: block;
    width: 100%;
    min-height: 80px;
}
.tylVideoPlayer--videojs10 video,
.tylVideoPlayer--videojs10 youtube-video,
.tylVideoPlayer--videojs10 hlsjs-video {
    width: 100%;
    height: 100%;
}
media-player.tylVideoPlayer:fullscreen {
    width: 100%;
    height: 100%;
    max-width: none;
}

.tylVideoPlayer--videojs10 tyl-video-skin::part(tyl-chapter-label) {
    flex: 1 1 auto;
    min-inline-size: 0;
    white-space: normal;
    overflow-wrap: anywhere;
}
.tylVideoPlayer--videojs10 tyl-video-skin::part(tyl-caption-preview) {
    display: block;
    margin: 8px;
    padding: 8px;
    color: white;
    background-color: black;
    text-align: center;
    font-size: 1.2em;
}
.tylVideoPlayer--videojs10 tyl-video-skin::part(tyl-chapter-time) {
    min-width: 4em;
    margin-inline-end: 12px;
    font-variant-numeric: tabular-nums;
}
.tylVideoPlayer--videojs10[data-caption-font="sans"] video::cue,
.tylVideoPlayer--videojs10[data-caption-font="sans"] tyl-video-skin::part(tyl-caption-preview) {
    font-family: sans-serif;
    font-variant: normal;
}
.tylVideoPlayer--videojs10[data-caption-font="serif"] video::cue,
.tylVideoPlayer--videojs10[data-caption-font="serif"] tyl-video-skin::part(tyl-caption-preview) {
    font-family: serif;
    font-variant: normal;
}
.tylVideoPlayer--videojs10[data-caption-font="monospace"] video::cue,
.tylVideoPlayer--videojs10[data-caption-font="monospace"] tyl-video-skin::part(tyl-caption-preview) {
    font-family: monospace;
    font-variant: normal;
}
.tylVideoPlayer--videojs10[data-caption-font="cursive"] video::cue,
.tylVideoPlayer--videojs10[data-caption-font="cursive"] tyl-video-skin::part(tyl-caption-preview) {
    font-family: cursive;
    font-variant: normal;
}
.tylVideoPlayer--videojs10[data-caption-font="smallcaps"] video::cue,
.tylVideoPlayer--videojs10[data-caption-font="smallcaps"] tyl-video-skin::part(tyl-caption-preview) {
    font-family: sans-serif;
    font-variant: small-caps;
}
.tylVideoPlayer--videojs10[data-caption-size="75"] video::cue,
.tylVideoPlayer--videojs10[data-caption-size="75"] tyl-video-skin::part(tyl-caption-preview) {
    font-size: 75%;
}
.tylVideoPlayer--videojs10[data-caption-size="100"] video::cue,
.tylVideoPlayer--videojs10[data-caption-size="100"] tyl-video-skin::part(tyl-caption-preview) {
    font-size: 100%;
}
.tylVideoPlayer--videojs10[data-caption-size="125"] video::cue,
.tylVideoPlayer--videojs10[data-caption-size="125"] tyl-video-skin::part(tyl-caption-preview) {
    font-size: 125%;
}
.tylVideoPlayer--videojs10[data-caption-size="150"] video::cue,
.tylVideoPlayer--videojs10[data-caption-size="150"] tyl-video-skin::part(tyl-caption-preview) {
    font-size: 150%;
}
.tylVideoPlayer--videojs10[data-caption-size="200"] video::cue,
.tylVideoPlayer--videojs10[data-caption-size="200"] tyl-video-skin::part(tyl-caption-preview) {
    font-size: 200%;
}
.tylVideoPlayer--videojs10[data-caption-text-color="white"] {
    --tyl-caption-text-rgb: 255, 255, 255;
}
.tylVideoPlayer--videojs10[data-caption-text-color="black"] {
    --tyl-caption-text-rgb: 0, 0, 0;
}
.tylVideoPlayer--videojs10[data-caption-text-color="red"] {
    --tyl-caption-text-rgb: 255, 0, 0;
}
.tylVideoPlayer--videojs10[data-caption-text-color="green"] {
    --tyl-caption-text-rgb: 0, 255, 0;
}
.tylVideoPlayer--videojs10[data-caption-text-color="blue"] {
    --tyl-caption-text-rgb: 0, 0, 255;
}
.tylVideoPlayer--videojs10[data-caption-text-color="yellow"] {
    --tyl-caption-text-rgb: 255, 255, 0;
}
.tylVideoPlayer--videojs10[data-caption-text-color="cyan"] {
    --tyl-caption-text-rgb: 0, 255, 255;
}
.tylVideoPlayer--videojs10[data-caption-text-color="magenta"] {
    --tyl-caption-text-rgb: 255, 0, 255;
}
.tylVideoPlayer--videojs10[data-caption-text-opacity="0"] {
    --tyl-caption-text-alpha: 0.0;
}
.tylVideoPlayer--videojs10[data-caption-text-opacity="25"] {
    --tyl-caption-text-alpha: 0.25;
}
.tylVideoPlayer--videojs10[data-caption-text-opacity="50"] {
    --tyl-caption-text-alpha: 0.5;
}
.tylVideoPlayer--videojs10[data-caption-text-opacity="75"] {
    --tyl-caption-text-alpha: 0.75;
}
.tylVideoPlayer--videojs10[data-caption-text-opacity="100"] {
    --tyl-caption-text-alpha: 1.0;
}
.tylVideoPlayer--videojs10[data-caption-text-color] video::cue,
.tylVideoPlayer--videojs10[data-caption-text-color] tyl-video-skin::part(tyl-caption-preview),
.tylVideoPlayer--videojs10[data-caption-text-opacity] video::cue,
.tylVideoPlayer--videojs10[data-caption-text-opacity] tyl-video-skin::part(tyl-caption-preview) {
    color: ~"rgba(var(--tyl-caption-text-rgb, 255, 255, 255), var(--tyl-caption-text-alpha, 1))";
}
.tylVideoPlayer--videojs10[data-caption-background-color="white"] {
    --tyl-caption-background-rgb: 255, 255, 255;
}
.tylVideoPlayer--videojs10[data-caption-background-color="black"] {
    --tyl-caption-background-rgb: 0, 0, 0;
}
.tylVideoPlayer--videojs10[data-caption-background-color="red"] {
    --tyl-caption-background-rgb: 255, 0, 0;
}
.tylVideoPlayer--videojs10[data-caption-background-color="green"] {
    --tyl-caption-background-rgb: 0, 255, 0;
}
.tylVideoPlayer--videojs10[data-caption-background-color="blue"] {
    --tyl-caption-background-rgb: 0, 0, 255;
}
.tylVideoPlayer--videojs10[data-caption-background-color="yellow"] {
    --tyl-caption-background-rgb: 255, 255, 0;
}
.tylVideoPlayer--videojs10[data-caption-background-color="cyan"] {
    --tyl-caption-background-rgb: 0, 255, 255;
}
.tylVideoPlayer--videojs10[data-caption-background-color="magenta"] {
    --tyl-caption-background-rgb: 255, 0, 255;
}
.tylVideoPlayer--videojs10[data-caption-background-opacity="0"] {
    --tyl-caption-background-alpha: 0.0;
}
.tylVideoPlayer--videojs10[data-caption-background-opacity="25"] {
    --tyl-caption-background-alpha: 0.25;
}
.tylVideoPlayer--videojs10[data-caption-background-opacity="50"] {
    --tyl-caption-background-alpha: 0.5;
}
.tylVideoPlayer--videojs10[data-caption-background-opacity="75"] {
    --tyl-caption-background-alpha: 0.75;
}
.tylVideoPlayer--videojs10[data-caption-background-opacity="100"] {
    --tyl-caption-background-alpha: 1.0;
}
.tylVideoPlayer--videojs10[data-caption-background-color] video::cue,
.tylVideoPlayer--videojs10[data-caption-background-color] tyl-video-skin::part(tyl-caption-preview),
.tylVideoPlayer--videojs10[data-caption-background-opacity] video::cue,
.tylVideoPlayer--videojs10[data-caption-background-opacity] tyl-video-skin::part(tyl-caption-preview) {
    background-color: ~"rgba(var(--tyl-caption-background-rgb, 0, 0, 0), var(--tyl-caption-background-alpha, 0.75))";
}
.tylVideoPlayer--videojs10[data-caption-edge="none"] video::cue,
.tylVideoPlayer--videojs10[data-caption-edge="none"] tyl-video-skin::part(tyl-caption-preview) {
    text-shadow: none;
}
.tylVideoPlayer--videojs10[data-caption-edge="shadow"] video::cue,
.tylVideoPlayer--videojs10[data-caption-edge="shadow"] tyl-video-skin::part(tyl-caption-preview) {
    text-shadow: 2px 2px 3px black;
}
.tylVideoPlayer--videojs10[data-caption-edge="outline"] video::cue,
.tylVideoPlayer--videojs10[data-caption-edge="outline"] tyl-video-skin::part(tyl-caption-preview) {
    text-shadow: -1px -1px 0 black, 1px -1px 0 black, -1px 1px 0 black, 1px 1px 0 black;
}
.tylVideoPlayer--videojs10[data-caption-edge="raised"] video::cue,
.tylVideoPlayer--videojs10[data-caption-edge="raised"] tyl-video-skin::part(tyl-caption-preview) {
    text-shadow: 1px 1px 0 black, -1px -1px 0 white;
}
.tylVideoPlayer--videojs10[data-caption-edge="depressed"] video::cue,
.tylVideoPlayer--videojs10[data-caption-edge="depressed"] tyl-video-skin::part(tyl-caption-preview) {
    text-shadow: -1px -1px 0 black, 1px 1px 0 white;
}

.tylVideoPlayer--videojs10 hlsjs-video > video {
    display: block;
    object-fit: var(--media-object-fit, contain);
    object-position: var(--media-object-position, center);
}
.tylVideoPlayer--videojs10 hlsjs-video > video::-webkit-media-text-track-container {
    transition: translate var(--media-caption-track-duration, 0s) ease-out;
    transition-delay: var(--media-caption-track-delay, 0s);
    translate: 0 var(--media-caption-track-y, 0px);
    scale: 0.98;
    z-index: 1;
    font-family: inherit;
}
